INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65221849', 65221849, 'analyze_legacy', 'Kementerian Hukum', 'central', '03 BALAI HARTA PENINGGALAN SEMARANG', 'Pengadaan Belanja Modal Peralatan dan Mesin berupa Camera Video Balai Harta Peninggalan Semarang Tahun Anggaran 2026', 'Barang', 'E-Purchasing', 'Jawa Tengah, Semarang (Kota)', 60000000, 'February 2026', 'APBN - PNBP (D)', 1, 0, '1 Paket', 'Uraian Pekerjaan Pengadaan Perangkat Dokumentasi 1. Nama Paket Pekerjaan Pengadaan Kamera Mirrorless Full Frame dan Lensa Sapujagat (All-around). 2. Ruang Lingkup Pekerjaan Penyediaan 1 (satu) unit kamera mirrorless profesional beserta 1 (satu) unit lensa zoom standar untuk menunjang kegiatan dokumentasi, publikasi, dan produksi konten visual instansi. 3. Spesifikasi Teknis Utama • Body Kamera: Sony Alpha A7 Mark IV (A7 IV) dengan sensor Full-Frame Exmor R CMOS 33MP, prosesor BIONZ XR, dan kemampuan rekam video 4K 60p 10-bit. • Lensa: Sony FE 24-240mm f/3.5-6.3 OSS (Optical SteadyShot). Lensa mount E-mount dengan rentang zoom 10x untuk fleksibilitas pengambilan gambar jarak dekat maupun jauh tanpa berganti lensa. 4. Kelengkapan Administrasi & Purna Jual • Barang dalam kondisi baru (BNIB) dan bergaransi resmi (Sony Indonesia). • Termasuk aksesori standar (Baterai, Charger, Strap, dan Kabel Data). • Layanan purna jual sesuai dengan ketentuan distributor resmi.', '• Sensor & Prosesor: 33 MP Full-Frame Exmor R CMOS sensor dengan prosesor BIONZ XR. • Video: Rekaman 4K 60p 10-bit 4:2:2, 4K 30p oversampled dari 7K, serta S-Cinetone untuk rona kulit yang lebih baik. • Autofokus: 759-point Fast Hybrid AF, Real-time Eye AF (Manusia, Hewan, Burung). • Stabilisasi: 5-Axis SteadyShot Inside (5.5 stop). • Kecepatan: Continuous shooting hingga 10 fps (dengan AF/AE tracking). • Layar & EVF: Layar sentuh vari-angle 3 inci (1.03m-dot) dan EVF 3.68m-dot dengan refresh rate 120 fps. • Fitur Tambahan: Focus breathing compensation, USB-C 10Gbps, slot ganda (CFexpress Type A/SD UHS-II), dan WiFi 5GHz. • Lensa - Panjang Fokus: 24-240mm (setara \\(36-360\\text{mm}\\) pada APS-C) - Bukaan Maksimum/Minimum: f/3.5-6.3 / f/22-40. - Kompatibilitas: Full-Frame Sony E-mount. - Fitur Stabilisasi: Optical SteadyShot (OSS) terintegrasi. - Jarak Fokus Minimum: 0,5 m (1,64 kaki) Maksimum Magnifikasi: 0.27x - Ukuran Filter: 72 mm.', 15000000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 2002574);
