INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65219911', 65219911, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN JUNIOR PENYUSUNAN DOKUMEN PEMBIAYAAN PERSAMPAHAN  KEGIATAN KOORDINASI REFORMASI PENGELOLAAN PERSAMPAHAN TERINTEGRASI DARI HULU KE HILIR DIT. PIKP', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 96600000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', '1. Mengumpulkan data mentah (raw data) ataupun menyusun data primer dan/atau sekunder terkait pembiayaan pengelolaan sampah di tingkat nasional dan di kabupaten/kota prioritas; 2. Mengidentifikasi gap pembiayaan pengelolaan sampah di tingkat nasional dan daerah termasuk gap pembiayaan antara dokumen perencanaan dan kebijakan nasional dan daerah dan realisasi anggarannya; 3. Melakukan pengolahan data perhitungan kebutuhan biaya pengelolaan sampah hulu ke hilir jangka pendek, menengah, dan panjang di tingkat nasional maupun daerah; 4. Mengidentifikasi dan memetakan opsi skema pembiayaan sesuai regulasi eksisting dalam sektor pengelolaan sampah; dan 5. Melakukan analisis pemetaan pemenuhan kebutuhan biaya pengelolaan (perhitungan tarif layanan, willingness to pay, availability to pay, chanelling pembiayaan).', '1. Pendidikan S1 bidang perencanaan (planologi/perencanaan wilayah/kebijakan publik/lainnya sejenis) atau lingkungan (teknik lingkungan/infrastruktur lingkungan/rekayasa lingkungan/ilmu lingkungan/lainnya sejenis) atau ekonomi pembangunan (ilmu ekonomi/ekonomi pembangunan/lainnya sejenis); 2. Diutamakan Tenaga ahli dalam negeri (dibuktikan dengan kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 3. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir terkait perencanaan pembangunan nasional (dibuktikan dengan kontrak); 4. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi, teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan) lingkup persampahan merupakan dalam kurun waktu 4 (empat) tahun; 5. Memiliki pengalaman kerja dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai total HPS/Pagu Anggaran; 6. Memiliki pengalaman kerja minimal 2 (dua) tahun dengan stakeholder pembangunan (pemerintah dan non-pemerintah) di sektor persampahan; dan 7. Memiliki kemampuan dalam menyusun laporan, kajian, maupun dokumen secara sistematis. 8. Bersedia tidak memperoleh hal-hal sebagai berikut : a. Barang Milik Negara; b. THR dan Gaji 13; c. BPJS (Kesehatan dan Ketenagakerjaan); d. Fasilitas klinik kecuali dalam kondisi darurat; dan e. Tidak Menuntut diangkat Menjadi ASN.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2004491);
