INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65185829', 65185829, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KAB MAJENE', 'Pengadaan Tenaga Pendukung Jasa Lainnya', 'Jasa Lainnya', 'E-Purchasing', 'Sulawesi Barat, Majene (Kab.)', 60000000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '2', '1)​Membantu menyiapkan bahan penyuluhan; 2)​Membantu kantor pertanahan menyiapkan list lokasi redistribusi dan legalisasi di seluruh Indonesia (sampai di tingkat desa) dan list lokasi potensial untuk dilakukan intervensi pemberdayaan; 3)​Melakukan kegiatan pemetaan sosial dengan menggunakan instrumen berbasis aplikasi baik melalui website maupun mobile; 4)​Bertugas sebagai supporting dalam mencapai output kegiatan; 5)​Membantu kantor pertanahan menyiapkan list lokasi redistribusi dan legalisasi di seluruh Indonesia (sampai di tingkat desa) dan list lokasi potensial untuk dilakukan intervensi pemberdayaan; 6)​Menyusun laporan hasil pemetaan sosial; 7)​Membantu petugas kantor pertanahan dalam penyusunan rekomendasi model pemberdayaan tanah masyarakat; 8)​Membantu petugas kantor pertanahan dalam setiap kegiatan yang berkaitan dengan kegiatan Penanganan Akses Reforma Agraria; 9)​Memotivasi masyarakat untuk berpartisipasi dalam seluruh kegiatan yang berkaitan dengan program pemberdayaan tanah masyarakat; 10)​Membantu dalam penginputan data Sistem Kendali Mutu Program Pertanahan (SKMPP) dan Sistem Monitoring dan Evaluasi (Sismonev) Kantor Staf Presiden secara berkala; 11)​Menyusun dan menyampaikan laporan pelaksanaan rangkaian kegiatan Penataan Akses Reforma Agraria yang diketahui oleh minimal Koordinator Substansi pada seksi Penataan dan Pemberdayaan kepada Pejabat Pembuat Komitmen; 12)​Menyusun Laporan Bulanan sebagai bentuk pertanggungjawaban administrasi.', '1)​Warga Negara Indonesia; 2)​Kualifikasi Pendidikan minimal D-III, diutamakan S1 dengan pengalaman kerja kurang dari 3 (tiga) tahun sesuai kebutuhan pemberi kerja; 3)​Diutamakan Tenaga Pendukung kegiatan Penataan Akses Reforma Agraria tahun sebelumnya; 4)​Memiliki kemampuan komunikasi, presentasi dan manajerial yang baik; 5)​Tidak berstatus ASN/TNI/Polri atau tidak sedang menjalani perjanjian/kontrak kerja/ikatan dinas dengan pihak manapun; 6)​Tidak menjadi anggota atau pengurus partai politik atau terlibat politik praktis; 7)​Mampu menggunakan dan mengoperasikan komputer (Microsoft Office) sesuai dengan kepentingan dan kebutuhan; 8)​Mampu bekerja sama dalam tim serta memiliki komitmen kuat di bidang pemberdayaan masyarakat; 9)​Bersedia bekerja penuh waktu (full time) dan diutamakan berdomisili di lokasi Penataan Akses Reforma Agraria; 10)​Memperhatikan kesetaraan gender; 11)​Sanggup bekerja dalam tekanan dan target waktu; 12)​Bersedia mengikuti pelatihan secara tatap muka dan/atau virtual.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2005112);
