INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65227201', 65227201, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Pedoman Teknis Penerapan Kebijakan Manajemen Risiko  Pembangunan Nasional (MRPN)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 90948000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '00', 'Lingkup kegiatan yang akan dilakukan oleh Jasa Konsultan Junior Penyusunan Pedoman Teknis Penerapan Kebijakan Manajemen Risiko Pembangunan Nasional (MRPN) ini, adalah sebagai berikut: Menyusun Pedoman Teknis Perencanaan Berbasis Risiko, meliputi pengumpulan data pendukung, analisis teknis risiko pembangunan, penyusunan draf, penyelarasan substansi, dan finalisasi pedoman. Menyusun bahan analisis dan laporan integrasi penguatan Budaya Risiko MRPN pada instansi pelaksana sebagai dukungan teknis penerapan MRPN. Menyusun dokumen teknis integrasi MRPN, termasuk konsep Objek MRPN Lintas Sektor dan Struktur UPR LS, bahan integrasi MRPN dalam RKP 2027, serta laporan akhir jasa konsultansi.', 'Output kegiatan Jasa Konsultan Junior Penyusunan Pedoman Teknis Penerapan Kebijakan Manajemen Risiko Pembangunan Nasional (MRPN) meliputi tersusunnya dokumen teknis Pedoman Teknis Perencanaan Berbasis Risiko sebagai acuan penerapan MRPN, tersusunnya bahan analisis dan laporan integrasi penguatan Budaya Risiko pada instansi pelaksana, tersusunnya dokumen teknis integrasi MRPN termasuk konsep Objek MRPN Lintas Sektor dan Struktur UPR LS serta bahan integrasi MRPN dalam RKP Tahun 2027, serta tersusunnya Laporan Penyusunan Pedoman Teknis Penerapan Kebijakan Manajemen Risiko Pembangunan Nasional (MRPN) sebagai bentuk pertanggungjawaban pelaksanaan kegiatan pengadaan, serta penjelasan keluaran setiap termin sebagai berikut: No Periode Keluaran per Termin 1 Termin 1 Laporan pengumpulan data dan informasi pendukung penyusunan Juklak Perencanaan Berbasis Risiko 2 Termin 2 Laporan draf awal Juklak Perencanaan Berbasis Risiko 3 Termin 3 Laporan hasil pembahasan substansi dan penyempurnaan Juklak Perencanaan Berbasis Risiko 4 Termin 4 Laporan integrasi penguatan Budaya Risiko pada instansi pelaksana MRPN. 5 Termin 5 Laporan penyusunan konsep Objek MRPN Lintas Sektor dan Struktur UPR LS serta integrasinya dalam RKP Tahun 2027. 6 Termin 6 Laporan Penyusunan Pedoman Teknis Penerapan Kebijakan Manajemen Risiko Pembangunan Nasional (MRPN).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2008280);
