INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65227657', 65227657, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN JUNIOR PENYUSUNAN KEBIJAKAN DAN PENGELOLAAN FISKAL DAERAH KEGIATAN KOORDINASI PENYUSUNAN RENCANA KERJA PEMERINTAH (RKP) DAN KEBIJAKAN DAK LINGKUP PERUMAHAN DAN INFRASTRUKTUR KAWASAN PERMUKIMAN', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 100000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', 'Mengumpulkan data dan dokumen terkait pengelolaan fiskal pusat-daerah bidang air minum; Menelaah dan menganalisis potensi inovasi bauran pendanaan pusat-daerah dalam pembangunan bidang air minum; Mempersiapkan bahan kajian (review) terhadap draf kebijakan pemerintah pusat untuk mendukung kapasitas fiskal daerah, termasuk identifikasi awal (diagnosis) permasalahan dan tantangan fiskal yang dihadapi Pemda pada bidang air minum; Melakukan penyiapan materi untuk kegiatan pendampingan teknis Pemerintah Daerah; Mendukung pelaksanaan peningkatan kapasitas bagi pemerintah pusat maupun pemerintah daerah, khususnya pada bidang penguatan perencanaan, kelembagaan dan pendanaan air minum; Pelaksanaan kegiatan lainnya sesuai dengan arahan dari Direktur Perumahan dan Infrastruktur Kawasan Permukiman, Kementerian PPN/Bappenas.', 'Pendidikan minimal S1 jurusan perencanaan wilayah dan kota/planologi (dibuktikan dengan ijazah); Diutamakan Tenaga ahli dalam negeri (dibuktikan dengan kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 1 (satu) tahun terakhir baik di lingkungan pemerintah maupun swasta (dibuktikan dengan kontrak) Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi atau karakteristik lainnya yang bisa menggambarkan kesamaan); Memiliki pengalaman kerja di bidang perencanaan minimal 1 tahun, pengalaman di bidang air minum atau sanitasi dan/atau perencanaan kewilayahan; Memiliki pengalaman dalam melakukan perencanaan terkait fiskal daerah (seperti dana transfer); Memiliki pengalaman dalam berkoordinasi dengan Kementerian/Lembaga dan Pemerintah Daerah; Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran; dan Bersedia tidak memperoleh hal-hal sebagai berikut : Barang Milik Negara; THR dan Gaji 13; BPJS (Kesehatan dan Ketenagakerjaan) Fasilitas klinik kecuali dalam kondisi darurat; dan Tidak Menuntut diangkat Menjadi ASN', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2008593);
