INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65188157', 65188157, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pekerjaan Pengadaan Jasa Konsultan Junior Pengembang dan Penerapan Sistem AI Deep Learning untuk Sistem Elektronik Perencanaan Pembangunan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99900000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Bulan', 'a. Mengidentifikasi kebutuhan layanan sistem Al (use case) di Kementerian PPN/Bappenas. b. Melakukan asesmen sistem yang sudah ada untuk menentukan titik integrasi Al dengan kebutuhan perubahan minimal. c. Menyusun rencana kerja pengembangan dan merancang arsitektur layanan sistem Al. d. Menetapkan pendekatan pemodelan deep learning sesuai kebutuhan (klasifikasi, prediksi, deteksi anomali, NLP). e. Merancang dan memvalidasi komponen pendukung layanan sistem Al berbasis pengetahuan pada sistem yang sudah ada (semantic search, embedding, RAG, information retrieval). f. Menyusun strategi pemanfaatan infrastruktur komputasi kinerja tinggi baik untuk pelatihan maupun inferensi. g. Mendefinisikan pola deployment dan kontrak layanan sistem Al dalam bentuk service yang dapat digunakan oleh sistem yang sudah ada (REST/gRPC/API internal). h. Merancang kerangka operasioanal monitoring dan pemeliharaan layanan sistem Al, termasuk penangan insiden dan perbaikan berkelanjutan. Memberikan pendampingan dan konsultasi penerapan Al kepada tim internal Pusdatinrenbang Pusat Sistem, Data, dan Informasi Perencanaan Pembangunan. I. Memberikan pendampingan dan konsultasi penerapan Al kepada tim internal Pusdatinrenbang. j. Mendukung operasi harian terkait layanan sistem Al dan dukungan teknis yang dibutuhkan Pusat Sistem, Data, dan Informasi Perencanaan Pembangunan. k. Menyusun laporan dan alih pengetahuan pelaksanaan kegiatan.', 'Pekerjaan Pengadaan Jasa Konsultan Junior Pengembang dan Penerapan Sistem AI Deep Learning untuk Sistem Elektronik Perencanaan Pembangunan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2008707);
