INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65227048', 65227048, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Kajian Penguatan Sistem dan Kebijakan Manajemen Risiko Pembangunan Nasional (MRPN) Lintas Sektor', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99900000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '00', 'Lingkup kegiatan yang akan dilakukan oleh Jasa Konsultan Penyusunan Kajian Penguatan Sistem dan Kebijakan Manajemen Risiko Pembangunan Nasional (MRPN) Lintas Sektor ini meliputi: Kajian indikator dan metodologi pengukuran efektivitas MRPN Lintas Sektor, meliputi reviu kebijakan dan praktik penerapan MRPN LS, perumusan indikator efektivitas, serta penyusunan metodologi pengukuran yang mendukung pencapaian sasaran pembangunan nasional. Penyusunan policy paper efektivitas MRPN Lintas Sektor, melalui analisis permasalahan dan isu strategis, perumusan alternatif kebijakan, serta penyampaian rekomendasi kebijakan berbasis risiko dan bukti empiris. Penyusunan indikasi profil risiko objek MRPN Lintas Sektor Tahun 2026, khususnya pada topik Makan Bergizi Gratis dan Pendidikan, yang mencakup identifikasi, analisis, dan perumusan mitigasi risiko strategis lintas sektor.', 'Jasa Konsultan Penyusunan Kajian Penguatan Sistem dan Kebijakan Manajemen Risiko Pembangunan Nasional (MRPN) Lintas Sektor memiliki keluaran berupa rekomendasi kebijakan dan perbaikan sistem MRPN LS serta penyelarasan kebijakan dan penguatan kerangka kerja dalam implementasi MRPN LS yang dituangkan dalam Laporan Penyusunan Kajian Penguatan Sistem dan Kebijakan Manajemen Risiko Pembangunan Nasional (MRPN) Lintas Sektor dan diterjemahkan dalam beberapa keluaran sebagai berikut: No Periode Keluaran per Termin 1 Termin 1 Laporan hasil kajian indikator dan metodologi pengukuran efektivitas MRPN LS 2 Termin 2 Policy Paper efektivitas MRPN LS 3 Termin 3 Laporan hasil Indikasi Profil Risiko Objek MRPN Lintas Sektor Tahun 2026 4 Termin 4 Laporan hasil pemantauan dan evaluasi pelaksanaan mitigasi risiko MRPN LS. 5 Termin 5 Laporan hasil reviu dan analisis pelaksanaan manajemen risiko MRPN LS 6 Termin 6 Laporan Penyusunan Kajian Penguatan Sistem dan Kebijakan Manajemen Risiko Pembangunan Nasional (MRPN) Lintas Sektor', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2008871);
