INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65227369', 65227369, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Kajian Pemantauan, Pelaporan dan Sistem Insentif Manajemen Risiko Pembangunan Nasional (MRPN)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 89808000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '00', 'Lingkup kegiatan Jasa Konsultan Junior Penyusunan Kajian Pemantauan, Pelaporan dan Sistem Insentif Manajemen Risiko Pembangunan Nasional (MRPN) mencakup dukungan kepada Direktorat Sistem dan Manajemen Risiko melalui penyusunan, konsultasi, dan sinkronisasi konsep integrasi MRPN ke dalam sistem e-Monev; pedoman mekanisme pemberian insentif MRPN; sistem manajemen pengetahuan MRPN Lintas Sektor; serta menyusun konsep integrasi MRPN dalam pengendalian dan evaluasi perencanaan dan pelaksanaan pembangunan nasional. Selain itu, kegiatan meliputi asistensi dan reviu pelaksanaan perlakuan risiko Objek MRPN; penyusunan laporan konsolidasi penyelenggaraan Objek MRPN Lintas Sektor pada UPR Lintas Sektor; serta penyusunan, konsultasi, dan koordinasi konsep integrasi MRPN dalam Laporan Kinerja Instansi Pemerintah (LAKIP).', 'Keluaran kegiatan di lingkup pekerjaan Jasa Konsultan Junior Penyusunan Kajian Pemantauan, Pelaporan dan Sistem Insentif Manajemen Risiko Pembangunan Nasional (MRPN) dalam mendukung pelaksanaan pekerjaan Direktorat Sistem dan Manajemen Risiko adalah Laporan Penyusunan Kajian Pemantauan, Pelaporan dan Sistem Insentif Manajemen Risiko Pembangunan Nasional (MRPN). Adapun keluaran setiap terminnya sebagai berikut: No Periode Keluaran per Termin 1 Termin 1 Laporan konsep sistem informasi e-Monev yang terintegrasi MRPN 2 Termin 2 Laporan konsep dan pedoman mekanisme pemberian insentif berbasis efektivitas MRPN 3 Termin 3 Laporan Kajian Desain dan Pengembangan Sistem Manajemen Pengetahuan MRPN LS 4 Termin 4 Laporan Kerangka Integrasi MRPN ke dalam tahapan Pengendalian dan Evaluasi Perencanaan dan Pelaksanaan Pembangunan Nasional 5 Termin 5 Laporan Kinerja Instansi Pemerintah (LAKIP) berbasis MRPN 6 Termin 6 Laporan Penyusunan Kajian Pemantauan, Pelaporan dan Sistem Insentif Manajemen Risiko Pembangunan Nasional (MRPN)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2008886);
