INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65188363', 65188363, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pekerjaan Pengadaan Jasa Konsultan Junior Penyusunan Pengembangan Generative AI', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 91500000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '10 Bulan', '1. Menyusun kajian dan usulan pengembangan modul rekayasa/perbaikan data yang difokuskan pada peningkatan kualitas input bagi model Generative Al; 2. Menyusun rancangan dan spesifikasi modul visualisasi data untuk mendukung interpretasi, pemantauan, serta evaluasi kinerja model Generative Al; 3. Merumuskan metode peningkatan pipeline pengembangan model generative Al, termasuk integrasi alat otomasi, CI/CD, serta MLOps, agar proses pengembangan, pengujian, dan penerapan model dapat berjalan lebih efisien dan terkelola dengan baik; 4. Menyusun rancangan arsitektural untuk pemanfaatan Machine Learning/Deep Learning/High Performance Computing dalam ekosistem Generative Al, mencakup perencanaan kapasitas, estimasi biaya, dan target performa, serta melakukan review terhadap rancangan teknis yang diusulkan.; 5. Menyusun blueprint arsitektur sistem Generative Al end-to-end (aplikasi, layanan model, penyimpanan, integrasi API), termasuk penetapan kriteria pemilihan model (opensource/komersial), pola deployment (on-prem/cloud/hybrid), serta strategi skalabilitas dan reliabilitas; 6. Menyusun rancangan integrasi, spesifikasi teknis, pola konektivitas, standar API, dan melakukan review/validasi implementasi integrasi yang dikerjakan tim teknis; 7. Bekerja sama dengan Tim Analitika dan tim terkait di Pusdatinrenbang atau di Bappenas sesuai penugasan untuk memahami kebutuhan data dan mengembangkan solusi yang sesuai; 8. Memberikan asistensi teknis lain sesuai kebutuhan dalam uji coba implementasi Kecerdasan Artifisial perencanaan pembangunan; 9. Merancang pendekatan observability dan monitoring end-to-end, termasuk rancangan logging, tracing, metrik operasional, dan aturan alerting berbasis SLO.; 10. Menyusun dokumentasi teknis dan alih pengetahuan yang mencakup dokumentasi arsitektur, pipeline, parameter, dependensi, struktur folder/kode serta workshop/sesi pelatihan, demo teknis, pendampingan staf internal; 11. Mendukung penyusunan laporan akhir kegiatan implementasi Kecerdasan Artifisial perencanaan pembangunan.', 'Pekerjaan Pengadaan Jasa Konsultan Junior Penyusunan Pengembangan Generative AI', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2009672);
