INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65227130', 65227130, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Pengembangan Fitur/Aplikasi/Database Sistem Informasi Manajemen Risiko Pembangunan Nasional (MRPN)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99900000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Lingkup kegiatan yang akan dilakukan oleh Jasa Konsultan Junior Pengembangan Fitur/Aplikasi/Database Sistem Informasi Manajemen Risiko Pembangunan Nasional (MRPN) ini meliputi: Memberikan rekomendasi analisis mendalam terhadap kebutuhan fungsional dan non-fungsional sistem berdasarkan brief dan arahan dari tim substansi. Memberikan rekomendasi dan mendukung integrasi arsitektur teknis sistem, termasuk model data, diagram alur proses, use case, dan desain teknis lainnya yang memerlukan kompetensi spesifik di bidang IT. Memberikan rekomendasi teknis terkait pemilihan teknologi, integrasi sistem, dan standar keamanan informasi. Mendukung pengembangan atau mengkoordinasikan pengembangan fitur sistem sesuai desain teknis yang telah disetujui oleh pimpinan/tim substansi. Dst Sesuai KAK', 'Hasil kerja Jasa Konsultan Junior Pengembangan Fitur/Aplikasi/Database Sistem Informasi Manajemen Risiko Pembangunan Nasional (MRPN) ini adalah Laporan Pengembangan Fitur/Aplikasi/Database Sistem Informasi Manajemen Risiko Pembangunan Nasional (MRPN) dengan waktu penyelesaian selama 11 (sebelas) bulan. Jasa Konsultan Junior Pengembangan Fitur/Aplikasi/Database Sistem Informasi Manajemen Risiko Pembangunan Nasional (MRPN) dalam mendukung Pekerjaan Direktorat Sistem dan Manajemen Risiko memiliki keluaran setiap periode terminnya sebagai berikut: No Periode Keluaran per Termin 1 Termin 1 Laporan Kajian Kebutuhan dan Rekomendasi Perancangan Konseptual Sistem MRPN Submodul e-Monev 2 Termin 2 Laporan Progres Pendampingan Teknis Pengembangan dan Integrasi Fungsional Sistem MRPN 3 Termin 3 Laporan Evaluasi Teknis dan Rekomendasi Optimalisasi Sistem MRPN 4 Termin 4 Laporan Evaluasi Pengujian Fungsional dan Rekomendasi Stabilitas Sistem MRPN 5 Termin 5 Laporan Kajian Keamanan Sistem dan Rekomendasi Mitigasi Risiko Teknis MRPN 6 Termin 6 Laporan Pengembangan Fitur/Aplikasi/Database Sistem Informasi Manajemen Risiko Pembangunan Nasional (MRPN)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2009776);
